export enum NumeralSystem {
  ARABIC = 'Arabic',
  ROMAN = 'Roman'
}

export enum DisplayMode {
  ANALOG = 'Analog',
  DIGITAL = 'Digital'
}

export interface ClockSettings {
  numeralSystem: NumeralSystem;
  displayMode: DisplayMode;
}

export const toRoman = (num: number): string => {
  const romanMap: Record<number, string> = {
    1: 'I', 2: 'II', 3: 'III', 4: 'IV', 5: 'V', 6: 'VI',
    7: 'VII', 8: 'VIII', 9: 'IX', 10: 'X', 11: 'XI', 12: 'XII'
  };
  return romanMap[num] || num.toString();
};

export const formatTwoDigits = (num: number): string => {
  return num.toString().padStart(2, '0');
};

import React from 'react';
import { NumeralSystem } from '../types';
import { toRoman } from '../utils';

interface AnalogClockProps {
  time: Date;
  numeralSystem: NumeralSystem;
}

const AnalogClock: React.FC<AnalogClockProps> = ({ time, numeralSystem }) => {
  const seconds = time.getSeconds();
  const minutes = time.getMinutes();
  const hours = time.getHours();

  // Rotations
  const secondsDeg = (seconds / 60) * 360;
  const minutesDeg = ((minutes + seconds / 60) / 60) * 360;
  const hoursDeg = (((hours % 12) + minutes / 60) / 12) * 360;

  const markers = Array.from({ length: 12 }, (_, i) => i + 1);

  return (
    <div className="relative w-72 h-72 md:w-96 md:h-96 flex items-center justify-center">
      {/* Outer Rim */}
      <div className="absolute inset-0 border-8 border-neutral-800 rounded-full shadow-[0_0_50px_rgba(0,0,0,0.5),inset_0_0_20px_rgba(255,255,255,0.05)] bg-[#121212]"></div>

      {/* Clock Face SVG */}
      <svg viewBox="0 0 400 400" className="w-full h-full transform transition-transform duration-700">
        {/* Markers */}
        {markers.map((num) => {
          const angle = (num * 30) * (Math.PI / 180);
          const x = 200 + 155 * Math.sin(angle);
          const y = 200 - 155 * Math.cos(angle);
          const label = numeralSystem === NumeralSystem.ROMAN ? toRoman(num) : num.toString();

          return (
            <text
              key={num}
              x={x}
              y={y}
              fill="white"
              fontSize={numeralSystem === NumeralSystem.ROMAN ? "24" : "28"}
              fontWeight="300"
              textAnchor="middle"
              dominantBaseline="middle"
              className={`${numeralSystem === NumeralSystem.ROMAN ? 'font-serif' : 'font-sans'} transition-all duration-500 opacity-80`}
            >
              {label}
            </text>
          );
        })}

        {/* Small Ticks */}
        {Array.from({ length: 60 }).map((_, i) => {
          if (i % 5 === 0) return null;
          const angle = (i * 6) * (Math.PI / 180);
          const x1 = 200 + 175 * Math.sin(angle);
          const y1 = 200 - 175 * Math.cos(angle);
          const x2 = 200 + 182 * Math.sin(angle);
          const y2 = 200 - 182 * Math.cos(angle);
          return (
            <line
              key={i}
              x1={x1} y1={y1} x2={x2} y2={y2}
              stroke="#444"
              strokeWidth="1"
            />
          );
        })}

        {/* Hour Hand */}
        <line
          x1="200" y1="200"
          x2={200 + 80 * Math.sin(hoursDeg * Math.PI / 180)}
          y2={200 - 80 * Math.cos(hoursDeg * Math.PI / 180)}
          stroke="#fff"
          strokeWidth="6"
          strokeLinecap="round"
        />

        {/* Minute Hand */}
        <line
          x1="200" y1="200"
          x2={200 + 120 * Math.sin(minutesDeg * Math.PI / 180)}
          y2={200 - 120 * Math.cos(minutesDeg * Math.PI / 180)}
          stroke="#fff"
          strokeWidth="4"
          strokeLinecap="round"
        />

        {/* Second Hand */}
        <line
          x1="200" y1="200"
          x2={200 + 140 * Math.sin(secondsDeg * Math.PI / 180)}
          y2={200 - 140 * Math.cos(secondsDeg * Math.PI / 180)}
          stroke="#ef4444"
          strokeWidth="2"
          strokeLinecap="round"
        />

        {/* Center Pin */}
        <circle cx="200" cy="200" r="6" fill="#000" stroke="#fff" strokeWidth="2" />
        <circle cx="200" cy="200" r="2" fill="#ef4444" />
      </svg>
    </div>
  );
};

export default AnalogClock;

import React from 'react';
import { NumeralSystem } from '../types';
import { toRoman, formatTwoDigits } from '../utils';

interface DigitalClockProps {
  time: Date;
  numeralSystem: NumeralSystem;
}

const DigitalClock: React.FC<DigitalClockProps> = ({ time, numeralSystem }) => {
  const hours = time.getHours();
  const minutes = time.getMinutes();
  const seconds = time.getSeconds();

  const displayHours = hours % 12 || 12;
  const amPm = hours >= 12 ? 'PM' : 'AM';

  const renderPart = (val: number, isHour: boolean = false) => {
    if (numeralSystem === NumeralSystem.ROMAN) {
      return toRoman(isHour ? (val % 12 || 12) : (val === 0 ? 0 : val));
    }
    return formatTwoDigits(val);
  };

  const numeralClass = numeralSystem === NumeralSystem.ROMAN ? 'font-serif' : 'font-mono';

  return (
    <div className="flex flex-col items-center justify-center space-y-4">
