        <div className="animate-pulse opacity-50">:</div>
        <div className="min-w-[2ch] text-center">{numeralSystem === NumeralSystem.ROMAN ? toRoman(minutes || 12) : formatTwoDigits(minutes)}</div>
        <div className="hidden md:flex items-baseline space-x-2">
            <div className="animate-pulse opacity-50 text-4xl md:text-6xl">:</div>
            <div className="text-4xl md:text-6xl text-red-500 opacity-80 min-w-[2ch]">{numeralSystem === NumeralSystem.ROMAN ? toRoman(seconds || 12) : formatTwoDigits(seconds)}</div>
        </div>
      </div>
      <div className="text-neutral-500 text-xl font-medium tracking-widest flex items-center space-x-2">
        <span>{amPm}</span>
        <span className="h-1 w-1 rounded-full bg-neutral-700"></span>
        <span className="uppercase text-sm tracking-tighter opacity-70">
          {time.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
